mapper.select:

where event = #{event} and alert_type = #{alertType}
and parent_id is null
order by sort

WITH RECURSIVE handler_cte AS ( SELECT a.id, a.uuid, a.name, a.alert_type as alertType, a.parent_id as parentId, a.handler, a.event, a.sort, a.is_async as isAsync, a.is_active as isActive, a.config as configStr, a.type_id as typeId, (select label from alert_event_handler_type x where x.id = a.type_id) as typeLabel, 1 AS level FROM alert_event_handler a
and a.parent_id is null
and a.parent_id = #{parentId}
and a.event = #{event}
and a.alert_type = #{alertType}
and a.handler = #{handler}
UNION ALL SELECT b.id, b.uuid, b.name, b.alert_type as alertType, b.parent_id as parentId, b.handler, b.event, b.sort, b.is_async as isAsync, b.is_active as isActive, b.config as configStr, b.type_id as typeId, (select label from alert_event_handler_type x where x.id = b.type_id) as typeLabel, cte.level + 1 AS level FROM alert_event_handler b INNER JOIN handler_cte cte ON b.parent_id = cte.id ) SELECT * FROM handler_cte ORDER BY sort;

SELECT a.id, a.uuid, a.name, a.alert_type as alertType, a.parent_id as parentId, a.handler, a.event, a.sort, a.is_async as isAsync, a.is_active as isActive, a.config as configStr, a.type_id as typeId, (select label from alert_event_handler_type x where x.id = a.type_id) as typeLabel FROM alert_event_handler a
and a.event = #{event}
and a.alert_type = #{alertType}
and a.handler = #{handler}
ORDER BY a.sort

select max(sort)
from alert_event_handler
where event = #{event}
  and alert_type = #{alertType}

mapper.update:
update alert_event_handler_audit
set result = #{resultStr, typeHandler=CompressHandler}
where id = #{id}

update alert_event_handler_audit
set
status = #{status},
end_time = now(3)

    ,result = #{resultStr,typeHandler=CompressHandler}


    ,error = #{error,typeHandler=CompressHandler}


    ,parent_id = #{parentId}

where id = #{id}

update alert_event_handler
set sort = #{sort}
where id = #{id}
